const fs=require('fs');const {chromium,webkit}=require('playwright');
const base=process.env.AUDIT_BASE||'http://127.0.0.1:8765/';
const pages=['links.html','index.html','brand.html','products.html','faq.html','guide.html','recipes.html','contact.html','choose.html','trial.html',...fs.readdirSync('.').filter(x=>/^product-.*\.html$/.test(x))];
(async()=>{const out='diagnostics/brand-20261003';fs.mkdirSync(out,{recursive:true});let failures=[];let checks=[];
for(const [engine,type] of Object.entries({chromium,webkit})){const browser=await type.launch();for(const [device,viewport] of Object.entries({desktop:{width:1440,height:1000},mobile:{width:390,height:844},small:{width:320,height:740}})){const context=await browser.newContext({viewport,deviceScaleFactor:1});for(const file of pages){const p=await context.newPage();const errs=[];p.on('pageerror',e=>errs.push(e.message));await p.goto(base+file,{waitUntil:'networkidle'});await p.evaluate(()=>window.scrollTo(0,document.body.scrollHeight));await p.waitForTimeout(300);await p.evaluate(()=>window.scrollTo(0,0));const r=await p.evaluate(()=>({overflow:document.documentElement.scrollWidth>innerWidth+1,broken:[...document.images].filter(i=>i.offsetWidth>0&&i.complete&&!i.naturalWidth).map(i=>i.src),manifest:document.querySelector('link[rel="manifest"]')?.getAttribute('href'),name:document.querySelector('meta[name="apple-mobile-web-app-title"]')?.content,links:[...document.querySelectorAll('a[href]')].map(a=>a.getAttribute('href'))}));if(r.overflow||r.broken.length||errs.length||r.name!=='仙加味'||!r.manifest)failures.push({engine,device,file,...r,errs});if(file==='links.html'&&!r.links.includes('https://lin.ee/sHZW7NkR'))failures.push({file,error:'LINE missing'});
if(file==='faq.html'){const detail=p.locator('details').first();if(await detail.count()){await detail.locator('summary').click();if(await detail.getAttribute('open')===null)failures.push({engine,device,file,error:'FAQ failed'});}}
if(['links.html','index.html','products.html','brand.html'].includes(file)&&device!=='small')await p.screenshot({path:`${out}/${engine}-${device}-${file}.png`,fullPage:true});checks.push({engine,device,file,pass:!r.overflow&&!r.broken.length&&!errs.length});await p.close();}await context.close();}await browser.close();}
const m=JSON.parse(fs.readFileSync('site.webmanifest'));if(m.name!=='仙加味'||m.short_name!=='仙加味'||!m.icons.some(x=>x.purpose==='maskable'))failures.push({error:'manifest invalid'});fs.writeFileSync(out+'/report.json',JSON.stringify({base,checks,failures},null,2));console.log(JSON.stringify({checks:checks.length,failures},null,2));if(failures.length)process.exit(1);})().catch(e=>{console.error(e);process.exit(1)});
